entries[191565] = { ["name"] = "Ensemble: Hingabe des Blutritters", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Paladin\nVölker: Blutelf\nBenutzen: Sammelt die Vorlagen der Hingabe des Blutritters, die nur von Blutelfenpaladinen verwendet werden kann.\n\"Ihr habt Gerissenheit, Entschlossenheit und Integrität bewiesen: die klassischen Merkmale der Blutritter.\"" }
entries[191566] = { ["name"] = "Flüchtiger Smaragdfalkenschreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren flüchtigen Smaragdfalkenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser bunt gefiederte Falkenschreiter wurde jahrelang nicht gesehen und kam jetzt aus seinem Versteck hervor, um zur Verteidigung der Geisterlande gegen die Geißel beizutragen. Dabei glänzt er so, wie seine Federn es tun.\"\nQuest:\nBlutritter\nZone:\nGeisterlande\n\nQuest:\nSieg für die Sin'dorei\nZone:\nGeisterlande" }
