entries[191582] = { ["name"] = "Rezept: Transmutieren: Verfall zu Element", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation verschiedener stabiler erweckter Elemente aus erwecktem Verfall.\nLäutert die Fäulnis des erweckten Verfalls, um eine Auswahl an tobenden Elementen zu erhalten.\nBenötigt Alchemie der Dracheninseln\n(25)\nVerkaufspreis:\nVerfall zu Element\n\"Läutert die Fäulnis des erweckten Verfalls, um eine Auswahl an tobenden Elementen zu erhalten.\"\nBenötigt Erweckter Verfall" }
entries[191583] = { ["name"] = "Rezept: Transmutieren: Ordnung zu Element", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation verschiedener stabiler erweckter Elemente aus erweckter Ordnung.\nZerstört ein zufälliges Element im Kern einer erweckten Ordnung und enthüllt im Gegenzug die drei verbliebenen Elemente.\nBenötigt Alchemie der Dracheninseln\n(25)\nVerkaufspreis:\nOrdnung zu Element\n\"Zerstört ein zufälliges Element im Kern einer erweckten Ordnung und enthüllt im Gegenzug die drei verbliebenen Elemente.\"\nBenötigt Erweckte Ordnung" }
