entries[191596] = { ["name"] = "Rezept: Glorreiche Einsicht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man glorreiche Einsicht herstellt.\nBenötigt Alchemie der Dracheninseln\n(25)\nVerkaufspreis:\nGlorreiche Einsicht\nWird beim Aufheben gebunden\nBenutzen: Zerbricht glorreiche Einsicht in 5 geringe glorreiche Einsichten.\nFertigungshandwerksmaterial\n\nBei der Herstellung: Erhöht Fertigkeit um 30.\nBenutzbar mit: Rezepte der Dracheninseln, deren Herstellung besonders aufwendig und herausfordernd ist.\nVerkaufspreis:\nBenötigt Eifer des Handwerkers (50)" }
