entries[191658] = { ["name"] = "Ensemble: Kleidung der Dunklen Waldläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenutzen: Sammelt die Vorlagen der Kleidung der Dunklen Waldläufer, die nur von Jägern verwendet werden kann.\nVerkaufspreis:" }
entries[191659] = { ["name"] = "Aschenscherbenkohle", ["text"] = "Questgegenstand" }
entries[191665] = { ["name"] = "Testwerkzeuge", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Analysiert alle instabilen Elementare in dem Gebiet.\n\"Ein Standardfeldprobentestwerkzeug für Mitglieder der Drachenschuppenexpedition. Es tickt und zischt ganz leise.\"" }
entries[191667] = { ["name"] = "Gealterter Schlüssel", ["text"] = "\"Scheint größtenteils intakt.\"\nVerkaufspreis:" }
entries[191668] = { ["name"] = "Gemeißelter Steinwal", ["text"] = "Questgegenstand\n\"Diese Schnitzerei in Form der Schwanzflosse eines flukenschlagenden Wals symbolisiert Erneuerung. Die Ränder der Flosse wurden von großen, scharfen Zähnen angenagt.\"" }
entries[191669] = { ["name"] = "Gravierter Stoßzahn", ["text"] = "Questgegenstand\n\"Ein sorgfältig dekorierter Mammutstoßzahn, der die Gebenden ehrt. Mit zähem, noch feuchtem Sabber überzogen.\"" }
entries[191670] = { ["name"] = "Perlengeschmücktes Federband", ["text"] = "Questgegenstand\n\"Mit Perlen und Lederbändern verflochtene Adlerfedern, die gutes Urteilsvermögen symbolisieren. Im Leder sind Bissspuren zu sehen und mehrere der Perlen sind gebrochen.\"" }
entries[191671] = { ["name"] = "Zerbrochenes Tuskarrbildnis", ["text"] = "Questgegenstand\n\"Ein abgetragenes Knochenbildnis eines verehrten Vorfahren der Tuskarr. In der Mitte stark angenagt.\"" }
entries[191672] = { ["name"] = "Siegel des Ernährers", ["text"] = "Questgegenstand\n\"Ein hervorragend geschnitztes Knochentotem, das einen erfolgreichen Fischer der Tuskarr darstellt. Durch tiefe Bissspuren haben sich Risse im Knochen gebildet.\"" }
entries[191673] = { ["name"] = "Grinsendes Delfinfetisch", ["text"] = "Questgegenstand\n\"Der lange, zahnbesetzte Schädel eines Delfins, der Führungsqualitäten symbolisiert. An mehreren Stellen angekaut.\"" }
entries[191676] = { ["name"] = "Konzentrierte Essenz des Wassers", ["text"] = "Questgegenstand\n\"Dieses magische Konzentrat wurde in einem Behälter untergebracht, der sich ideal dazu eignet, auf widerspenstige Feuerelementare geworfen zu werden.\"" }
entries[191680] = { ["name"] = "Gestohlene Teile", ["text"] = "Questgegenstand\n\"Leicht klebrig, sehr fischig.\"" }
entries[191681] = { ["name"] = "Federführende Kreischerschwarmverkleidung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ein Original von Hohnzirper!\n\"Dazu gedacht, Kreischerschwarmharpyien davon abzuhalten, Euch sofort töten zu wollen! Zum Patent angemeldet!\"" }
entries[191682] = { ["name"] = "Explosiver Kuchen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft mit einem Kuchen nach einem schlafenden Arbeiter. (3 Sek. Abklingzeit)" }
