entries[191701] = { ["name"] = "Beutel voller erkundeter Seelen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Die Erleuchteten\n- Wohlwollend\n\"Dieser Beutel enthält Überreste der Verlorenen von Torghast - genug Seelenasche und Seelenglut, damit ein Runenmetz einen mächtigen legendären Gegenstand herstellen kann.\"\n<Zum Öffnen rechtsklicken>" }
entries[191702] = { ["name"] = "Matildas Lieblingsangelrute", ["text"] = "Questgegenstand" }
entries[191703] = { ["name"] = "Merkwürdig großes Gorlocauge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n70 ( 70)\n\"Ein merkwürdig großes Gorlocauge.\"" }
entries[191719] = { ["name"] = "Klebriger Schlüssel", ["text"] = "Questgegenstand\nEinzigartig\n\"Von einer unbekannten Substanz bedeckt.\"" }
entries[191729] = { ["name"] = "Toxingegenmittel", ["text"] = "Questgegenstand\nBenutzen: Verzehren, um die Giftigkeit stark zu verringern. (5 Sek. Abklingzeit)" }
entries[191730] = { ["name"] = "Hornsignet von Tenezeth", ["text"] = "Questgegenstand\n\"Ein für Dracthyrverhältnisse einfaches Signet.\"" }
entries[191731] = { ["name"] = "Hornsignet von Rethenasch", ["text"] = "Questgegenstand\n\"Verziert mit verzauberten Runen, die mehr der Zierde als einem Zweck dienten.\"" }
entries[191732] = { ["name"] = "Hornsignet von Katrinasa", ["text"] = "Questgegenstand\n\"Notizen über einen Testzauber wurden ins Innere dieses Rings gekritzelt.\"" }
entries[191733] = { ["name"] = "Bericht: Befall", ["text"] = "Questgegenstand\n\"In einer alten Sprache verzauberte Runen.\"\n<Zum Lesen rechtsklicken>" }
entries[191734] = { ["name"] = "Magisches Elixier des schwindelgeplagten Peons", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Riecht vielleicht nach Krötenatem und Talbukschweiß, aber dem Orc nach verhindert es, dass die Welt sich bewegt, und das klingt gerade ziemlich gut. (5 Sek. Abklingzeit)\n\"Kann nur im Grimmgleisdepot, dem Schlund der Seelen, in der Schwarzfelsgießerei oder in der Drachenseele verwendet werden.\"\nVerkaufspreis:" }
