entries[191763] = { ["name"] = "Federführende Kreischerschwarmverkleidung v2", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Aufgemotzt, aufgewertet und aufge-federt! Jetzt mit Kochmütze!\n\"Aufgemotzt, aufgewertet und aufge-federt! Jetzt mit Kochmütze!\"" }
