entries[192295] = { ["name"] = "Wildheitsabzeichen des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 42.\nBenutzen: Erhöht den Primärwert 15 Sek. lang um 74 . (1 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[192296] = { ["name"] = "Inbrunstinsigne des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 42.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 62 zu erhöhen.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[192297] = { ["name"] = "Emblem des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 2714 . (2 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[192298] = { ["name"] = "Medaillon des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[192299] = { ["name"] = "Unerbittliche Brosche des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Verringert die Dauer eintreffender Kontrollverlusteffekte um 20%. Nicht mit ähnlichen Effekten stapelbar.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[192300] = { ["name"] = "Siegel der Anpassung des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[192301] = { ["name"] = "Akribische Entschlossenheit des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Aktiviert die Mittlerverteidigung und schützt Euch so vor Zauberunterbrechungen und Kontrollverlusteffekten. Die Verteidigung hält bis zu 2 Effekte ab und bleibt 12 Sek. lang bestehen.\nVerkaufspreis:" }
entries[192302] = { ["name"] = "Hallende Entschlossenheit des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Erhöht die Dauer eintreffender Kontrollverlusteffekte um 25%. Nicht mit ähnlichen Effekten stapelbar. Schützt Betroffene für 12 Sek. vor dem nächsten Kontrollverlusteffekt. (500ms Abklingzeit)\nVerkaufspreis:" }
entries[192303] = { ["name"] = "Resonator des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Werft den kosmischen Resonator. Dieser explodiert nach 4 Sek. und verursacht 2039 kosmischen Schaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner, für bis zu 5 Gegner. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[192304] = { ["name"] = "Ewige Aegis des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Aktiviert die Verteidigung und absorbiert für 15 Sek. 50% sämtlichen erlittenen Magieschadens, bis zu maximal [ 2339 * (1 + Vielseitigkeit)] Schaden. Kosmischer Schaden wird vollständig absorbiert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[192305] = { ["name"] = "Verschlingende Verwünschung des ewigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 42 Vielseitigkeit\nBenutzen: Entzieht allen Gegnern in der Nähe im Verlauf von 3 Sek. bis zu ( 752 * 4) Absorption und entfesselt sie in einem kegelförmigen Bereich von 20 Metern vor Euch als heilende Absorption. (3 Min Abklingzeit)\nVerkaufspreis:" }
