entries[192743] = { ["name"] = "Wilde Strauchfrucht", ["text"] = "Questgegenstand\nBenutzen: Verfüttert eine wilde Strauchfrucht an einen hungrigen Schlammstampfer innerhalb von 20 Metern. (3 Sek. Abklingzeit)\n\"Eine herrlich knusprige, kühle Minzexplosion.\"" }
entries[192744] = { ["name"] = "Rymeks Geschenk", ["text"] = "Questgegenstand\n\"Dynamische, wenn auch äußerst kalte Edelsteine.\"" }
entries[192745] = { ["name"] = "Die titanische Komödie", ["text"] = "Questgegenstand\n\"Eine satirische Reise durch den Kosmos vom Smaragdgrünen Traum bis zu den Schattenlanden, angeführt vom Titanenhüter Dantyr. Weder die Titanen noch die Aspekte sind vor des Autors Grimm sicher und ihre erkannten Sünden werden offen zur Schau gestellt.\"" }
