entries[192747] = { ["name"] = "Zerbrochener Ast", ["text"] = "Verkaufspreis:" }
entries[192749] = { ["name"] = "Chronokristall", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stimmt das Ziel auf die für es richtige Zeitlinie ab." }
entries[192750] = { ["name"] = "Schwarzeisenspeer", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Auf einen urzeitlichen Wahrblütigen werfen, um ihn vom Himmel zu holen. (5 Sek. Abklingzeit)" }
entries[192751] = { ["name"] = "Sturmberührter Brüffelch", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\"" }
entries[192752] = { ["name"] = "Stabkopfstück", ["text"] = "Questgegenstand\n\"Der abgetrennte Fokus eines zerbrochenen Zeitwandererstabs.\"" }
entries[192753] = { ["name"] = "Die Schuppen des Zorns", ["text"] = "Questgegenstand\n\"Eine schonungslose und messerscharfe Widerlegung der Ordnung, die von den Aspekten und ihren Titanenverbündeten verhängt wurde. Erzählt aus der Perspektive eines Protodrachen, der sich schließlich gezwungen sieht zu rebellieren, nachdem man ihn an den Rand der drakonischen Gesellschaft getrieben hatte.\"" }
entries[192754] = { ["name"] = "Dracuixote", ["text"] = "Questgegenstand\n\"Die Geschichte eines uralten grünen Drachen, der seine Träume nicht mehr von der Wirklichkeit unterscheiden konnte. In Begleitung der Drachenbrut Dracuixote, die selbst eine lange Leidensgeschichte hat, macht er sich an die abstruse Mission, ein vermeintliches goldenes Zeitalter zurückzubringen.\"" }
entries[192755] = { ["name"] = "Der Fürst der Schwingen", ["text"] = "Questgegenstand\n\"Eine Truppe aus kampferprobten Drakoniden und tapferen Welpen findet zusammen, um ein Artefakt von schrecklicher Macht zu zerstören. Vernichten lässt sich das unheilvolle Artefakt jedoch nur in der Schmiede des wahnsinnigen Aspekts, der es einst erschuf...\"" }
entries[192756] = { ["name"] = "Der rote und der schwarze Schwarm", ["text"] = "Questgegenstand\n\"Ein schwarzer Drache von niederem Stand hadert damit, seine militärische Herkunft mit seiner Wertschätzung für Intelligenz und Wortgewandtheit zu vereinen. Unerwiderte Liebe und der Materialismus, der in der Drachenheit grassiert, treiben ihn am Ende zur Verzweiflung.\"" }
entries[192757] = { ["name"] = "Stolz und Protodrachen", ["text"] = "Questgegenstand\n\"Die ultimative Liebesgeschichte aus einer Zeit vor den Aspekten. Ein forscher junger Protodrache legt sich mit einem unnahbaren Ältesten an. Aus Feindseligkeit wird Wertschätzung und irgendwann Liebe, als sie beginnen, einander zu verstehen.\"" }
entries[192758] = { ["name"] = "Rolle mit schwerem Seil", ["text"] = "Questgegenstand\n\"Schwer für die Drachkin. Ihr könntet mit einer einzigen Rolle vermutlich ganze Felsbrocken abschleppen.\"" }
entries[192759] = { ["name"] = "Magmagebundener Speer", ["text"] = "Questgegenstand\n\"Auf den Gegner richten und fest zustoßen.\"" }
entries[192761] = { ["name"] = "Gezähmte Flatterlibelle", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 25 bei der Drachenschuppenexpedition.\n\n\"Es dauerte nicht lang, bis Opa Schnurrbart die Flatterlibellen um das Drachenschuppenbasislager gezähmt und dazu gebracht hatte, Personal und Fracht der Expedition zu transportieren.\"\nFraktion:\nDrachenschuppenexpedition\nRuhmstufe:\n25\nVerkäufer:\nOpa Schnurrbart\nOrt:\nDrachenschuppenbasislager" }
entries[192762] = { ["name"] = "Azurflatterlibelle", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 25 bei der Drachenschuppenexpedition.\n\n\"Nachdem Opa Schnurrbart ihnen endlich beigebracht hatte, jemanden zu tragen, haben die Azurflatterlibellen sich als äußerst loyal ihren Reitern gegenüber erwiesen, mit denen sie eine enge Bindung eingehen.\"\nFraktion:\nDrachenschuppenexpedition\nRuhmstufe:\n25\nVerkäufer:\nOpa Schnurrbart\nOrt:\nDrachenschuppenbasislager\nKosten:\n5\n20\n750" }
entries[192764] = { ["name"] = "Tiefgrüne Flatterlibelle", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Tiefgrüne Flatterlibellen sind die perfekten Reittiere für die Späher der Drachenschuppenexpedition, da sie schnell sind und mit dem Blätterdach der Dracheninseln verschmelzen.\"\nFraktion:\nDrachenschuppenexpedition\nRuhmstufe:\n25\nSchatz:\nExpeditionsspäherpack" }
entries[192765] = { ["name"] = "Überlassener Sandhuscher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese unberechenbaren Flatterlibellen waren ein Geschenk von Opa Schnurrbart und helfen den Zeitwanderern, die gegenwärtigen (und zukünftigen) sandbezogenen Zeitkatastrophen aufzuräumen.\"\nErfolg:\nSperrstunde\nKategorie:\nErkundung" }
entries[192766] = { ["name"] = "Bernsteingelbe Flatterlibelle", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk von Opa Schnurrbart an den Handelsposten. Bernsteingelbe Flatterlibellen sind erstaunlich zahm.\"\nHandelsposten" }
entries[192767] = { ["name"] = "Tasche voller Erz", ["text"] = "Questgegenstand" }
entries[192768] = { ["name"] = "Scheibe der Titanen", ["text"] = "Questgegenstand\n\"Auf dieser Scheibe der Titanen befinden sich einige komplexe Symbole und sie sendet ein schwaches Leuchten aus.\"" }
entries[192769] = { ["name"] = "Gesprungener Speer", ["text"] = "\"Diese Waffe ist für den Kampf unbrauchbar geworden.\"\nVerkaufspreis:" }
entries[192772] = { ["name"] = "Uralter Salamanther", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Aufgrund ihrer Vorliebe für dunkle Höhlen und trübe Gewässer wird diese einzigartige Spezies der Salamanther so selten gesehen, dass viele Forscher dachten, sie sei ausgestorben.\"\nBeute von:\nVerbotene Insel" }
entries[192774] = { ["name"] = "Korallenschuppensalamanther", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Raszageths Stürme sich legten, war diese Art aquatischer Salamanther eines der vielen Wunder, die sich an den Küsten in ihrer Spur ansiedelten.\"\nErfolg:\nIn den Sturm\nKategorie:\nErkundung" }
entries[192775] = { ["name"] = "Sturmbalgsalamanther", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn Sturmenergie eine Kreatur erfüllt, wird sie manchmal einfach... größer und gelassener. Nur wenige Salamanther lassen sich reiten, doch diese Kinder des Sturms sind eine bemerkenswerte Ausnahme.\"\nVerkäufer:\nMythressa\nKosten:\n2.000" }
entries[192776] = { ["name"] = "Inaktiver Glutkegel", ["text"] = "Questgegenstand\n\"Dieser Samen fühlt sich warm an und enthält genug Energie, um in schwindelnde Höhen zu wachsen.\"" }
entries[192777] = { ["name"] = "Magmahäuschen", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Na, wer ist denn hier eine neue ganz aus Elementarlava geschmiedete Schnecke? Das bist ganz allein du! Ja!\"\nGegenstand:\nLeerer Magmapanzer\nZone:\nKüste des Erwachens" }
entries[192779] = { ["name"] = "Brodelnde Schnecke", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Durch die Wut der Zaqali aus ihrem Abgrund hervorgerissen.\"\nSchatz:\nBrodelnde Truhe\nZone:\nZaralekhöhle" }
entries[192783] = { ["name"] = "Frontkämpferbefehle der Nokhud", ["text"] = "Questgegenstand\n\"Vom Leichnam einer Assassine der Nokhud genommen.\"\n<Zum Lesen rechtsklicken>" }
entries[192784] = { ["name"] = "Panzerklatscher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die von Siegen genährte und von Ruhm gestählte Schnecke repräsentiert die Huldigung der Meisterschaft.\"\nErfolg:\nRuhm des Helden von Dragonflight" }
entries[192785] = { ["name"] = "Schleimiger Schneckelementar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses magische Weichtier ist aus der übrig gebliebenen Elementarenergie der Urstürme geformt und schneller als erwartet.\"\nBeute von:\nVerbotene Insel" }
entries[192786] = { ["name"] = "Schneckenhaus einer schlummernden Weltenschnecke", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Für die Weltenbrecher ist es ein tragbarer Schemel, für Euch ist es ein widerstandsfähiges Reittier.\"\nVerkäufer:\nHändlerin Vexil\nZone:\nKüste des Erwachens\nKosten:\n1.000" }
entries[192788] = { ["name"] = "Überlassenes Fischermammut", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk von Späherin Tomul, damit die Festmahle von Iskaara immer genug Fisch zur Verfügung haben mögen, um die Bedürftigen zu nähren.\"\nErfolg:\nArmee der Genährten\nKategorie:\nErkundung" }
entries[192790] = { ["name"] = "Moosmammut", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses Mammut wurde über Tausende von Jahren in Stein konserviert und durch Bronzemagie beinahe zurück in ein Fossil gealtert.\"\nBeute von:\nGewölbe von Zskera" }
entries[192791] = { ["name"] = "Ebenenschreiterträger", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Mammuts der Ebenen von Ohn'ahra sind es nicht gewohnt, jemanden zu tragen, da ihre Nachbarn, die Zentauren, üblicherweise nicht reiten. Doch sie können lernen, Reiter zu tragen. Manche tun es sogar sehr gerne.\"\nWeltereignis:\nZentaurenjagd (erste Jagd jeder Woche)" }
entries[192792] = { ["name"] = "Überlassenes Leittier der Donnerrückgrate", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk von Merithra, die diese Donnerrückgrate gesegnet hat, damit sie stets unter dem Schutz des grünen Drachenschwarms stehen, egal, wohin es die Klans der Maruuk treibt.\"\nErfolg:\nZentaur der Aufmerksamkeit\nKategorie:\nErkundung" }
