entries[192795] = { ["name"] = "Trunk der Verjüngung", ["text"] = "Questgegenstand\nBenutzen: Stärkt einen verletzten Soldaten der Gelikyr auf der unteren Terrasse des Rundblicks der Gelikyr.\n\"Die Phiole ist mit einer viskosen prismatischen Flüssigkeit gefüllt.\"" }
entries[192796] = { ["name"] = "Steinbalgpacktier des Forschers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein wahrer Entdecker bleibt nie lange an einem Ort. Ein zuverlässiges Packtier mit kräftigem Rücken und starken Beinen ist für die Reisen unerlässlich.\"\nVerkäuferin:\nVersorgerin Aristta\nZone:\nThaldraszus\nKosten:\n20.000" }
entries[192797] = { ["name"] = "Grals abgelegter Zahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure offensiven Zauber und Fähigkeiten haben eine hohe Chance, einen Geisterhai zu beschwören, der 4230 Frostschaden verursacht, die auf Euer Ziel sowie Gegner in der Nähe aufgeteilt werden.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu 5 Gegner.\nVerkaufspreis:" }
entries[192799] = { ["name"] = "Lizis Zügel", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Lizi, den Donnerrückgrattrampler, beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nichts wird Lizi von ihrer Mission abhalten, alle Früchte der Welt zu probieren.\"\nQuest:\nDonnerrückgrat zähmen leicht gemacht\nZone:\nEbenen von Ohn'ahra" }
entries[192800] = { ["name"] = "Himmelshauthornschreiter", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Instabilität der Primalistenstürme in möglichen Zeitlinien führt gelegentlich dazu, dass Kreaturen Energie aus diesen Stürmen absorbieren. Diese Kreaturen zeigen sich in der Regel zahm gegenüber jenen, die dem Zorn dieser chronomatischen Anomalien standhalten können.\"\nVerkäufer:\nBrendormi\nKosten:\n150\n3.000" }
