entries[192805] = { ["name"] = "Wildtierprobe", ["text"] = "Questgegenstand\n\"Eine Probe der Wildtiere aus der Umgebung des Titanentempels.\"" }
entries[192806] = { ["name"] = "Wütendes Magmammut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die meiste Lava fließt. Diese hier greift an.\"\nErfolg:\nRuhm des Gewölbeschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[192807] = { ["name"] = "Erneuertes Magmammut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses Magmammut wurde nach seiner Vernichtung durch die Druiden der Flamme neu geschmiedet und ist bereit, alle Gegner auf seinem Weg niederzutrampeln.\"\nBeute:\nTraumsprünge" }
entries[192808] = { ["name"] = "Befehle der Primalisten", ["text"] = "Questgegenstand\n\"Auf das Pergament sind Pläne der Primalisten zur Invasion von Tyrhold gekritzelt.\"" }
entries[192809] = { ["name"] = "Temporalrückstände", ["text"] = "Questgegenstand\nHandwerksmaterial\n\"Die Sande der Zeit bedecken die, die auf den Pfaden der Zeit verloren gingen.\"" }
entries[192810] = { ["name"] = "Korb mit getrocknetem Fisch", ["text"] = "Questgegenstand\n\"Ein Korb voller Fische, gesalzen und getrocknet für die Reise.\"" }
entries[192811] = { ["name"] = "Waffen der Shikaar", ["text"] = "Questgegenstand\n\"Prächtige Shikaarspeere, die für Präzision bei der Jagd geschmiedet wurden.\"" }
entries[192812] = { ["name"] = "Wildblütenkapsel", ["text"] = "Questgegenstand\n\"Gemahlen und mit Wasser und Honig vermischt wird daraus eine lindernde Paste, die offene Wunden heilt.\"" }
entries[192833] = { ["name"] = "Verformte Filigranarbeit", ["text"] = "Handwerksmaterial\n\"Erhältlich bei Juwelierskunstverkäufern auf den Dracheninseln. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[192872] = { ["name"] = "Zerbrochenes Glas", ["text"] = "Handwerksmaterial\n\"Wird von Juwelenschleifern durch das Sondieren von Erzen der Dracheninseln gewonnen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[192880] = { ["name"] = "Zerbröckelter Stein", ["text"] = "Handwerksmaterial\n\"Wird von Juwelenschleifern durch das Sondieren von Erzen der Dracheninseln gewonnen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[192893] = { ["name"] = "Juwelenbesetztes Drachenherz", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein ausgezeichneter, wenn auch fragiler Edelstein. Offenbart, wenn er aufgebrochen wird, einen kleinen Vorrat an Juwelen der Dracheninseln.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[192996] = { ["name"] = "Anhänger der bevorstehenden Gefahren", ["text"] = "Wird beim Anlegen gebunden\nHals\n+82 Ausdauer\n+ 136 Zufallswert 1\n+ 136 Zufallswert 2\nVerkaufspreis:" }
entries[192997] = { ["name"] = "Juwelensignet des blutroten Kämpfers", ["text"] = "Wird beim Anlegen gebunden\nFinger\n+182 Ausdauer\n+ 287 Vielseitigkeit\nVerkaufspreis:" }
entries[192998] = { ["name"] = "Juwelenbesetztes Amulett des blutroten Kämpfers", ["text"] = "Wird beim Anlegen gebunden\nHals\n+182 Ausdauer\n+ 287 Vielseitigkeit\nVerkaufspreis:" }
entries[192999] = { ["name"] = "Siegel der titanischen Einsicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+234 Ausdauer\n+ 360 Zufallswert 1\n+ 360 Zufallswert 2" }
entries[193000] = { ["name"] = "Ringgebundenes Stundenglas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+234 Ausdauer\n+ 360 Zufallswert 1\n+ 360 Zufallswert 2\nBenutzen: Besucht einen Ort, den Ihr vielleicht schon längst vergessen habt. (20 Std. Abklingzeit)" }
entries[193001] = { ["name"] = "Elementarschleife", ["text"] = "Wird beim Aufheben gebunden\nHals\n+234 Ausdauer\n+ 360 Zufallswert 1\n+ 360 Zufallswert 2\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, einen Eurer gesockelten Elementaredelsteine zu ermächtigen und Euch dadurch 313 des entsprechenden Werts zu gewähren. Hält 5 Sek. lang und weitere 1 Sek. pro Elementaredelstein an.\nVerkaufspreis:" }
entries[193002] = { ["name"] = "Halsreif der Abschirmung", ["text"] = "Wird beim Aufheben gebunden\nHals\n+234 Ausdauer\n+ 360 Zufallswert 1\n+ 360 Zufallswert 2\nBenutzen: Zieht Elementarenergien aus Euch und Euren Edelsteinen und opfert jeweils 31 des entsprechenden Werts, um Euch für 10 Sek. einen Schild in Höhe von 13907 pro gesockeltem Edelstein zu gewähren.\n\nIhr erhaltet diese Werte zurück, wenn der Schild durchbrochen wird oder abläuft. (3 Min Abklingzeit)" }
entries[193003] = { ["name"] = "Götze der Lebensbinderin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Götze der Aspekte (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren kritischen Trefferwert pro ausgerüstetem Alexstraszit um 34 zu erhöhen. Bei 18 Stapeln werden alle Stapel verbraucht und Eure Sekundärwerte werden 15 Sek. lang gleichmäßig um insgesamt 573 erhöht.\n\"Morgen erwarten Euch neue Herausforderungen, und Ihr müsst bereit sein, ihnen gegenüberzutreten.\"\nVerkaufspreis:" }
entries[193004] = { ["name"] = "Götze des Spruchwirkers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Götze der Aspekte (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Eure Vielseitigkeit pro ausgerüstetem Malygit um 34 zu erhöhen. Bei 18 Stapeln werden alle Stapel verbraucht und Eure Sekundärwerte werden 15 Sek. lang gleichmäßig um insgesamt 573 erhöht.\n\"Ich habe in meiner Zeit viel verloren, sterbliches Wesen, eigentlich zu viel.\"\nVerkaufspreis:" }
entries[193005] = { ["name"] = "Götze der Träumerin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Götze der Aspekte (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euer Tempo pro ausgerüstetem Ysmaragd um 34 zu erhöhen. Bei 18 Stapeln werden alle Stapel verbraucht und Eure Sekundärwerte werden 15 Sek. lang gleichmäßig um insgesamt 573 erhöht.\n\"Was immer kommen mag, ich weiß, dass Ihr ihm mit Mut begegnen werdet.\"\nVerkaufspreis:" }
entries[193006] = { ["name"] = "Götze des Erdwächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Götze der Aspekte (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Eure Meisterschaft pro ausgerüstetem Neltharit um 34 zu erhöhen. Bei 18 Stapeln werden alle Stapel verbraucht und Eure Sekundärwerte werden 15 Sek. lang gleichmäßig um insgesamt 573 erhöht.\n\"Es ist vollbracht. Alle haben gegeben, was gegeben werden musste. Nun werde ich die Drachenseele für immer versiegeln.\"\nVerkaufspreis:" }
entries[193032] = { ["name"] = "Juwelenbesetzte Opfergabe", ["text"] = "Spielzeug\nBenutzen: Bietet demütig Euren wertvollsten Besitz demjenigen dar, der Euch als würdig genug erachtet, ihn anzunehmen. (1 Tag Abklingzeit)\nVerkaufspreis:" }
entries[193033] = { ["name"] = "Konvergentes Prisma", ["text"] = "Spielzeug\nBenutzen: Nehmt das verzauberte Prisma fest in die Hand, um einen sehr präzisen Lichtstrahl zu lenken.\n\nDer Strahl ist nur für Mitglieder Eurer Gruppe oder Eures Schlachtzugs sichtbar. (5 Sek. Abklingzeit)\nVerkaufspreis:" }
