entries[193395] = { ["name"] = "Stundenglas der Wandernden Sande", ["text"] = "Questgegenstand\n\"Der Sand im Stundenglas wirkt wie eingefroren und schwebt schwerelos zwischen den gläsernen Wänden, unabhängig von jeglicher Störung.\"" }
