entries[193401] = { ["name"] = "Blutbefleckter Großgürtel aus Moschushirschfell", ["text"] = "Questgegenstand\n\"Dieser wertvolle Besitz des verstorbenen Balakar Khans hat mit ihm schon viele Schlachten erlebt.\"" }
entries[193402] = { ["name"] = "Fetisch der Faultriarchin", ["text"] = "Questgegenstand\n\"Dieser filigrane Fetisch scheint schon am Verrotten zu sein.\"" }
entries[193403] = { ["name"] = "Kristallfokus", ["text"] = "Questgegenstand\n\"Der Fokus scheint den Ursprung des kristallinen Wuchses darzustellen.\"" }
entries[193404] = { ["name"] = "Kern der wässrigen Verderbnis", ["text"] = "Questgegenstand\n\"Wenn der Kern seinem Wirt entnommen wird, beginnt er, sich langsam aufzulösen.\"" }
entries[193405] = { ["name"] = "Geschäftsbuch der Direktorin", ["text"] = "Questgegenstand\n\"Auf dem Titelblatt steht: \"Schüler, Lehren und Studien\". Allerdings wurden alle weiteren Seiten mit viel Gewalt herausgerissen.\"" }
