entries[193411] = { ["name"] = "Glutgebundener Anhänger", ["text"] = "Questgegenstand\n\"Gravuren auf der Rückseite des steinernen Anhängers deuten darauf hin, dass er einer von vielen ist, jeder davon mit eigenem Siegel verziert. Er ist noch warm.\"" }
entries[193412] = { ["name"] = "Urenergieerfülltes Drachenei", ["text"] = "Questgegenstand\n\"Schon lange haust kein Leben mehr in dieser einstigen warmen Hülle.\"" }
entries[193413] = { ["name"] = "Feder der Himmelsmutter", ["text"] = "Questgegenstand\n\"Eine Berührung mit der Feder reicht aus, um tausend Geister in sicherere Reiche zu geleiten.\"" }
entries[193414] = { ["name"] = "Alter Schamanendolch", ["text"] = "Questgegenstand\n\"Obwohl er abgenutzt und verwittert ist, wurde der Dolch wohl selten im Kampf genutzt.\"" }
entries[193415] = { ["name"] = "Sindragosas Aufzeichnungen", ["text"] = "Questgegenstand\n\"Eine Reihe detaillierter Aufzeichnungen zu Umbrelskuls Zustand.\"" }
entries[193416] = { ["name"] = "Holografischer Verteiler", ["text"] = "Questgegenstand\n\"An einer Seite des merkwürdigen runden Geräts befindet sich ein Platz für eine Art Schlüssel. Vielleicht handelt es sich dabei um eine Sicherheitsvorkehrung, um den Inhalt zu beschützen.\"" }
entries[193417] = { ["name"] = "Traumirrwisch der verworrenen Erinnerungen", ["text"] = "Questgegenstand\n\"Flüstern entspringt dem zerbrechlichen Gehäuse in einer sanften und unverständlichen Stimme.\"" }
